396	export function latestAsk<T extends ThreadEntry & { at?: string }>(
397	  body: string,
398	  comments: readonly T[],
399	  readers: AskReaders,
400	): LatestAsk | undefined {
401	  const { comments: kept } = shapedThread(comments, readers);
402	  for (let index = kept.length - 1; index >= 0; index -= 1) {
403	    const entry = kept[index]!;
