406	    if (agent === "") continue;
407	    if (readers.isDispatchMarker(entry.body)) continue;
408	    if (entry.isHuman) return { agent, author: { kind: "person" }, at: entry.at ?? "" };
409	    const author = readers.authoringAgent(entry.body);
410	    if (author === "") return undefined;
411	    return { agent, author: { kind: "agent", agent: author }, at: entry.at ?? "" };
412	  }
