416	/**
417	 * Whether an agent was ever dispatched onto this node, from its thread.
418	 *
419	 * The `atomaton/launched` label used to answer this, and it was written BEFORE the
420	 * dispatch was attempted -- so a dispatch that was refused (a closed target, a request
421	 * already outstanding) left the label saying "launched" while nothing had been. The
422	 * dispatch marker is written by `dispatchRunner` itself, and only when it is about to
423	 * start a run, so the thread is the accurate record.
424	 *
425	 * Read from the shaped thread, which is safe because a dispatch marker is the
426	 * machinery's own comment and the guard never removes one -- so shaping cannot change
427	 * the answer.
428	 */
429	export function wasLaunched(comments: readonly ThreadEntry[], readers: TurnReaders): boolean {
430	  return comments.some((entry) => readers.isDispatchMarker(entry.body));
